tasks.implementationGuide:
interface Event { id: string; title: string; description: string | null; location: string; eventDate: string; coverImageUrl: string | null; inviteCode: string; status: EventStatus; createdBy: string; participantCount: number; createdAt: string; updatedAt: string }
interface EventWithParticipants extends Event { participants: EventParticipant[] }
interface CreateEventInput { title: string; description?: string; location: string; eventDate: string; coverImageUrl?: string }
interface UpdateEventInput extends Partial<CreateEventInput> {}

type UserRole = 'user' | 'admin'
interface User { id: string; email: string; name: string; avatarUrl: string | null; role: UserRole; createdAt: string; updatedAt: string }
interface PublicProfile { id: string; name: string; avatarUrl: string | null }

interface ApiError { message: string; code?: string }
type ApiResponse<T> = { data: T; error: null } | { data: null; error: ApiError }
interface PaginatedResponse<T> { items: T[]; total: number; page: number; pageSize: number }

interface DashboardMetrics { eventsToday: number; eventsThisWeek: number; eventsThisMonth: number; eventsTotal: number; usersToday: number; usersThisWeek: number; usersTotal: number }
interface AdminEventRow { id: string; title: string; hostName: string; eventDate: string; participantCount: number; status: EventStatus; createdAt: string }
interface AdminUserRow { id: string; name: string; email: string; avatarUrl: string | null; role: UserRole; createdAt: string; createdEventsCount: number; joinedEventsCount: number }
type StatsPeriod = '7d' | '30d' | '90d'
interface TimeSeriesPoint { date: string; count: number }

interface EventCardProps { event: Event; href: string }
interface ParticipantCardProps { participant: EventParticipant }
interface EmptyStateProps { title: string; description?: string; actionLabel?: string; onAction?: () => void }
interface LoadingSkeletonProps { count?: number; variant?: 'card' | 'row' }
